##################################################
# Script: 15_drug_prediction_GraphBAN.R
#
# Purpose:
# Analysis workflow for the study:
# Integrating genetic risk and single-cell transcriptomics
# identifies a stromal migrasome-related signature in ulcerative colitis
#
# This script was prepared for reproducible research.
# Please configure input/output paths before execution.
##################################################
# Input files should be placed under data/ and resources/.
# Output files should be written under results/.
##################################################


rm(list = ls())
gc()

setwd(dirname(rstudioapi::getActiveDocumentContext()$path))
project_dir <- dirname(rstudioapi::getActiveDocumentContext()$path)
cat("工作目录：", getwd(), "/n")
library(dplyr)

# 读入候选药物表
drug_df <- read.csv("DrugReflector_Results.csv", stringsAsFactors = FALSE)

# 定义四个蛋白的 FASTA 序列
adamts1_seq <- ""

fbn1_seq <- ""

sparc_seq <- ""

vcam1_seq <- ""

# 生成配对数据框（每个药物 × 四个蛋白）
input_list <- data.frame()
for (i in 1:nrow(drug_df)) {
  drug_name <- drug_df$compound[i]
  drug_smiles <- drug_df$smiles[i]
  # 分别添加四个蛋白
  input_list <- rbind(input_list,
                      data.frame(drug = drug_name, smiles = drug_smiles,
                                 protein = "ADAMTS1", sequence = adamts1_seq,
                                 stringsAsFactors = FALSE))
  input_list <- rbind(input_list,
                      data.frame(drug = drug_name, smiles = drug_smiles,
                                 protein = "FBN1", sequence = fbn1_seq,
                                 stringsAsFactors = FALSE))
  input_list <- rbind(input_list,
                      data.frame(drug = drug_name, smiles = drug_smiles,
                                 protein = "SPARC", sequence = sparc_seq,
                                 stringsAsFactors = FALSE))
  input_list <- rbind(input_list,
                      data.frame(drug = drug_name, smiles = drug_smiles,
                                 protein = "VCAM1", sequence = vcam1_seq,
                                 stringsAsFactors = FALSE))
}

# 保存为 CSV
write.csv(input_list, "GraphBAN_input.csv", row.names = FALSE)
